import{_ as t,o as a,c as r,ah as s}from"./chunks/framework.D4KxWb5R.js";const c=JSON.parse('{"title":"Bureaux et départements","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration/referentials.md","filePath":"src/guide/administration/referentials.md"}'),n={name:"guide/administration/referentials.md"};function i(o,e,l,u,p,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="bureaux-et-departements" tabindex="-1">Bureaux et départements <a class="header-anchor" href="#bureaux-et-departements" aria-label="Permalink to &quot;Bureaux et départements&quot;">​</a></h1><p>Les référentiels de l&#39;organisation sont réservés au PDG. Ils ne se suppriment pas. Les zones relèvent du <a href="./registry.html#zones">registre</a> et les équipes ont <a href="./teams.html">leur page</a>.</p><h2 id="bureaux" tabindex="-1">Bureaux <a class="header-anchor" href="#bureaux" aria-label="Permalink to &quot;Bureaux&quot;">​</a></h2><p><strong>Administration → Bureaux</strong> liste les implantations physiques de M&#39;City.</p><ol><li><strong>Nouveau bureau</strong>.</li><li>Saisissez le nom et choisissez la <strong>zone</strong> où il se trouve.</li><li><strong>Créer le bureau</strong>.</li></ol><p>Les bureaux servent au périmètre des comptes Support N1 et N2, et de cible aux communications. Cibler une zone atteint aussi les comptes dont un bureau est dans cette zone.</p><h2 id="departements" tabindex="-1">Départements <a class="header-anchor" href="#departements" aria-label="Permalink to &quot;Départements&quot;">​</a></h2><p><strong>Administration → Départements</strong> liste les pôles et volets de M&#39;City, avec le nombre de comptes rattachés.</p><ol><li><strong>Nouveau département</strong>.</li><li>Saisissez le nom.</li><li><strong>Créer le département</strong>.</li></ol><p>Un compte est rattaché à un département depuis sa fiche ; une équipe peut l&#39;être aussi. Les départements servent de cible aux communications.</p>',10)])])}const h=t(n,[["render",i]]);export{c as __pageData,h as default};
